// Package lru implements a fixed-capacity least-recently-used cache.
package lru

const nilSlot = -1

type entry struct {
	key, value string
	prev, next int32
}

// Cache is a fixed-capacity LRU cache mapping string keys to string values.
// Entries live in a slice and form an intrusive doubly linked list ordered
// from most to least recently used; every operation is O(1) expected.
// The zero value is not usable; construct one with New.
type Cache struct {
	capacity int
	index    map[string]int32
	entries  []entry
	free     []int32
	head     int32 // most recently used
	tail     int32 // least recently used
}

// New returns an empty cache that holds at most capacity keys.
// It panics if capacity is not positive.
func New(capacity int) *Cache {
	if capacity <= 0 {
		panic("lru: capacity must be positive")
	}
	return &Cache{
		capacity: capacity,
		index:    make(map[string]int32),
		head:     nilSlot,
		tail:     nilSlot,
	}
}

// Len reports the number of keys currently held.
func (c *Cache) Len() int { return len(c.index) }

// Get returns the value stored for key and marks it most recently used.
func (c *Cache) Get(key string) (string, bool) {
	slot, ok := c.index[key]
	if !ok {
		return "", false
	}
	c.moveToFront(slot)
	return c.entries[slot].value, true
}

// Set inserts or overwrites key, marks it most recently used, and evicts the
// least recently used key if the cache would exceed its capacity.
func (c *Cache) Set(key, value string) {
	if slot, ok := c.index[key]; ok {
		c.entries[slot].value = value
		c.moveToFront(slot)
		return
	}
	if len(c.index) >= c.capacity {
		c.release(c.tail)
	}
	var slot int32
	if n := len(c.free); n > 0 {
		slot = c.free[n-1]
		c.free = c.free[:n-1]
	} else {
		slot = int32(len(c.entries))
		c.entries = append(c.entries, entry{})
	}
	c.entries[slot].key = key
	c.entries[slot].value = value
	c.index[key] = slot
	c.pushFront(slot)
}

// Delete removes key and reports whether it was present.
func (c *Cache) Delete(key string) bool {
	slot, ok := c.index[key]
	if !ok {
		return false
	}
	c.release(slot)
	return true
}

func (c *Cache) release(slot int32) {
	c.unlink(slot)
	e := &c.entries[slot]
	delete(c.index, e.key)
	*e = entry{}
	c.free = append(c.free, slot)
}

func (c *Cache) unlink(slot int32) {
	e := &c.entries[slot]
	if e.prev == nilSlot {
		c.head = e.next
	} else {
		c.entries[e.prev].next = e.next
	}
	if e.next == nilSlot {
		c.tail = e.prev
	} else {
		c.entries[e.next].prev = e.prev
	}
}

func (c *Cache) pushFront(slot int32) {
	e := &c.entries[slot]
	e.prev = nilSlot
	e.next = c.head
	if c.head == nilSlot {
		c.tail = slot
	} else {
		c.entries[c.head].prev = slot
	}
	c.head = slot
}

func (c *Cache) moveToFront(slot int32) {
	if slot == c.head {
		return
	}
	c.unlink(slot)
	c.pushFront(slot)
}

package lru

import "testing"

func TestEvictionOrder(t *testing.T) {
	c := New(2)
	c.Set("a", "1")
	c.Set("b", "2")
	if v, ok := c.Get("a"); !ok || v != "1" {
		t.Fatalf("Get(a) = %q, %v", v, ok)
	}
	c.Set("c", "3")
	if _, ok := c.Get("b"); ok {
		t.Fatal("b should have been evicted")
	}
	if c.Len() != 2 {
		t.Fatalf("Len = %d, want 2", c.Len())
	}
}

func TestOverwriteRefreshes(t *testing.T) {
	c := New(2)
	c.Set("a", "1")
	c.Set("b", "2")
	c.Set("a", "9")
	c.Set("c", "3")
	if v, _ := c.Get("a"); v != "9" {
		t.Fatalf("Get(a) = %q, want 9", v)
	}
	if _, ok := c.Get("b"); ok {
		t.Fatal("b should have been evicted")
	}
}

func TestDeleteReusesSlots(t *testing.T) {
	c := New(3)
	c.Set("x", "1")
	if !c.Delete("x") || c.Delete("x") {
		t.Fatal("Delete should report presence exactly once")
	}
	for _, k := range []string{"a", "b", "c", "d"} {
		c.Set(k, k)
	}
	if c.Len() != 3 || len(c.entries) != 3 {
		t.Fatalf("Len = %d, slots = %d; want 3, 3", c.Len(), len(c.entries))
	}
	if _, ok := c.Get("a"); ok {
		t.Fatal("a should have been evicted")
	}
}

// Command app simulates an LRU cache driven by commands read from stdin.
// See SPEC.md for the input format.
package main

import (
	"bufio"
	"bytes"
	"fmt"
	"io"
	"os"
	"strconv"

	"lru-sim/lru"
)

func main() {
	if err := run(os.Stdin, os.Stdout); err != nil {
		fmt.Fprintln(os.Stderr, "app:", err)
		os.Exit(1)
	}
}

func run(r io.Reader, w io.Writer) error {
	input, err := io.ReadAll(r)
	if err != nil {
		return fmt.Errorf("reading input: %w", err)
	}

	first, rest, _ := bytes.Cut(input, []byte{'\n'})
	capacity, err := strconv.Atoi(string(bytes.TrimSpace(first)))
	if err != nil || capacity < 1 {
		return fmt.Errorf("invalid capacity %q", first)
	}
	cache := lru.New(capacity)

	out := bufio.NewWriterSize(w, 64<<10)
	for len(rest) > 0 {
		var line []byte
		line, rest, _ = bytes.Cut(rest, []byte{'\n'})
		line = bytes.TrimSuffix(line, []byte{'\r'})
		if len(line) == 0 {
			continue
		}
		execute(cache, line, out)
	}
	if err := out.Flush(); err != nil {
		return fmt.Errorf("writing output: %w", err)
	}
	return nil
}

// execute applies one command line to cache, writing any result to out.
// Unknown commands are ignored.
func execute(cache *lru.Cache, line []byte, out *bufio.Writer) {
	cmd, args, _ := bytes.Cut(line, []byte{' '})
	key, args, _ := bytes.Cut(args, []byte{' '})
	switch string(cmd) {
	case "SET":
		value, _, _ := bytes.Cut(args, []byte{' '})
		cache.Set(string(key), string(value))
	case "GET":
		if v, ok := cache.Get(string(key)); ok {
			out.WriteString(v)
		} else {
			out.WriteString("NULL")
		}
		out.WriteByte('\n')
	case "DEL":
		if cache.Delete(string(key)) {
			out.WriteString("1\n")
		} else {
			out.WriteString("0\n")
		}
	case "SIZE":
		out.WriteString(strconv.Itoa(cache.Len()))
		out.WriteByte('\n')
	}
}
